const data = $input.first().json;
const metrics = data.metrics || {};
const openTasks = data.openTasks || [];

// 3 Priorities for the upcoming week
const priorities = openTasks
  .filter(t => t.priority === 'urgent' || t.priority === 'high')
  .slice(0, 3)
  .map(t => `${t.title} (${t.priority} priority)`);

if (!priorities.length && openTasks.length) {
  priorities.push(openTasks[0].title);
}

// 2-3 Practical Improvements
const improvements = [
  `Routine Consistency: Completed habits on ${metrics.successfulRoutineDays || 0} of ${metrics.eligibleRoutineDays || 0} scheduled days (${metrics.routineConsistencyRate || 0}%). Target 85%+ consistency.`,
  metrics.overdueCount > 0 ? `Clear ${metrics.overdueCount} overdue tasks early this week to eliminate context switching.` : 'Zero overdue tasks backlog — maintain this clean cadence!',
  'Protect a 90-minute morning deep work block for your highest priority task.'
];

return [{
  json: {
    ...data,
    priorities,
    improvements,
    emailSubject: data.email?.subject || `Weekly Productivity Report (${data.period?.label})`,
    emailHtml: data.email?.html,
    emailText: data.email?.text,
  }
}];
